-- The Ceramic insert code key on the Grades (Ceramic) tab (editable there); kept if one exists.
INSERT INTO "AppSetting" ("key", "value") VALUES ('codekey.ceramic', $ck${"title": "Code key for Ceramic inserts – ISO 1832", "example": "CNGA 120408 WL T01020 IS45C", "sections": [{"title": "Chip breaker or Wiper", "sample": "WL", "rows": [{"code": "AG", "meaning": "Chip breaker"}, {"code": "WL", "meaning": "Wiper"}]}, {"title": "Edge preparation – Standard", "sample": "T", "rows": [{"code": "S", "meaning": "Chamfer + rounded (honing)"}, {"code": "E", "meaning": "Rounded (honing)"}, {"code": "T", "meaning": "Chamfer (negative land)"}, {"code": "P", "meaning": "Double bevel (chamfer) + rounded"}]}, {"title": "Chamfer width and honing", "sample": "010", "rows": [{"code": "T010", "meaning": "0.10 mm"}, {"code": "T020", "meaning": "0.20 mm"}, {"code": "E002", "meaning": "0.02 mm"}, {"code": "E004", "meaning": "0.04 mm"}, {"code": "…", "meaning": "Additional sizes available"}]}, {"title": "Chamfer angle", "sample": "20", "rows": [{"code": "20", "meaning": "20°"}, {"code": "30", "meaning": "30°"}, {"code": "…", "meaning": "Additional sizes available"}]}, {"title": "Ceramic grade", "sample": "IS45", "rows": [{"code": "ISxx", "meaning": "Ceramic grade (substrate and coating, if applicable)"}]}, {"title": "Coating", "sample": "C", "rows": [{"code": "C", "meaning": "Coated inserts"}]}]}$ck$)
ON CONFLICT ("key") DO NOTHING;
